import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1788283385000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><p>This page is the prose version of <a href="https://github.com/ni-c/healthchecks-mcp/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to “Trust model”">​</a></h2><p>A Healthchecks API key is scoped to <strong>one project</strong>. A read-write key grants everything the web UI can do to that project&#39;s checks: read them, change their schedules and notification integrations, pause them, delete them.</p><p>Two of those deserve naming individually.</p><ul><li><strong>Deleting a check destroys its UUID irrecoverably.</strong> Every deployed script still pinging that URL breaks, and no new check can take the old UUID.</li><li><strong>Pausing a check switches its alerting off.</strong> It is reversible and it is quiet, which is the dangerous combination: the dashboard stops complaining and so does the job that stopped running.</li></ul><p>The key also reads <strong>ping bodies</strong> — the output jobs POST when they report in. That is often the most sensitive data in a monitoring system: stack traces, hostnames, file paths, occasionally a credential a script printed by accident. A read-only key cannot reach ping bodies at all, which makes it the right key for most uses of this server.</p><p>Treat every environment variable this server reads as a secret. The MCP client process, and therefore the model driving it, sees every tool result — do not point this server at a project whose ping bodies you would not put in a model&#39;s context.</p><h2 id="what-the-key-cannot-do" tabindex="-1">What the key cannot do <a class="header-anchor" href="#what-the-key-cannot-do" aria-label="Permalink to “What the key cannot do”">​</a></h2><p>It cannot ping. Ping URLs are authenticated by a <strong>ping key</strong>, a separate per-project secret that the Management API does not expose, and this server never calls one.</p><p>That is a deliberate boundary, not an omission. Pinging is a job&#39;s statement that it ran. A tool able to ping would let a model report success for something that never executed — and since this same server hands the model ping bodies written by whatever pings the check, that would close a loop from untrusted text to falsified monitoring. There is no such tool, so there is no such loop.</p><h2 id="the-confirmation-honestly" tabindex="-1">The confirmation, honestly <a class="header-anchor" href="#the-confirmation-honestly" aria-label="Permalink to “The confirmation, honestly”">​</a></h2><p>One tool asks a person before it acts: <code>delete_check</code>. Where the MCP client supports elicitation that is a <strong>dialog</strong> shown to whoever is sitting there — the model cannot answer it on their behalf, and nothing happens until an answer comes back.</p><p>A boolean could be set on the very first call, including by a model that read an instruction telling it to.</p><p>Where the client cannot show a dialog, the tool falls back to a random 32-hex token with a five-minute lifetime, single-use, bound to a SHA-256 fingerprint of <em>this operation on this check</em>. Be clear about what that proves, because this server is: <strong>the call was made twice with the same arguments, and nothing more.</strong> A model can read the token out of the first result and quote it back in the same turn. The fallback text says so rather than implying somebody approved, and names whether it was the client that could not be asked or the operator who switched the dialog off with <code>ELICITATION=false</code>.</p><div class="info custom-block"><p class="custom-block-title"><code>pause_check</code> used to be gated, and is not any more</p><p>Pausing switches alerting off, which is quiet rather than loud — but <code>resume_check</code> puts it back and nothing is lost in between. A dialog in front of a reversible state change is how people learn to tick without reading, and that attention is what <code>delete_check</code> needs. What pausing costs is stated in the tool&#39;s description instead.</p></div><p>The prompt quotes <strong>no</strong> name, description or tag from Healthchecks. Those are free text this server does not control and that text is read by a model.</p><p>See <a href="/guide/approval">Asking a person</a> for what the dialog contains, which clients show one, and what <code>ELICITATION=false</code> does and does not change.</p><h2 id="untrusted-content" tabindex="-1">Untrusted content <a class="header-anchor" href="#untrusted-content" aria-label="Permalink to “Untrusted content”">​</a></h2><p><code>get_ping_body</code> returns whatever POSTed it. <code>get_check</code> returns a free-text description. Both are wrapped with an explicit marker saying they are data and not instructions.</p><p>The marker is a signal, not a sandbox: it makes the boundary visible to the model rather than enforcing it. The enforcement is elsewhere — in the confirmation tokens, which no amount of text in a ping body can satisfy, and in <code>HEALTHCHECKS_READ_ONLY</code>, which removes the write tools from existence rather than declining them.</p><h2 id="limits-and-truncation" tabindex="-1">Limits and truncation <a class="header-anchor" href="#limits-and-truncation" aria-label="Permalink to “Limits and truncation”">​</a></h2><p>Every response is read with a byte ceiling enforced <em>while it streams</em>, not after, because <code>content-length</code> is absent on a chunked response. A JSON document that would have to be cut is refused rather than returned half-parsed. Ping bodies are capped at 64 KB and say when they were truncated. Upstream error bodies are cut to 2000 characters, and HTML error pages — a reverse proxy&#39;s or a WAF&#39;s — are dropped entirely rather than pasted into the context.</p><p>The Management API paginates nothing, so <code>list_checks</code> and <code>list_pings</code> apply their own ceiling, drop whole entries rather than cutting the JSON, and name the argument that narrows the request.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to “Reporting a vulnerability”">​</a></h2><p>Use <a href="https://github.com/ni-c/healthchecks-mcp/security/advisories/new" target="_blank" rel="noreferrer">private vulnerability reporting</a>. Do not open a public issue for an unpatched vulnerability, and do not include real API keys, hostnames or ping bodies in a report.</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};